WITH b AS (
  SELECT 1 FROM ally_berechtigungen WHERE matrix_user_id = $1::text AND aktiv = true
), e AS (
  INSERT INTO matrix_verarbeitete_events (event_id)
  SELECT $2::text WHERE EXISTS (SELECT 1 FROM b)
  ON CONFLICT (event_id) DO NOTHING
  RETURNING event_id
)
SELECT (SELECT count(*) FROM e)::int AS neu;

