// Talent-Datei erkennen (Stefan 18.10.2026, Vertrag Migration 47 §6): Paket Talents gebucht und Beschriftung "Zahlen <Name>",
// "Statistik von <Name>" oder "Insights: @account" -> Zahlen auslesen statt Beleg. Sonst unverändert Beleg.
// Erlaubt: PNG, JPG, WEBP, PDF, CSV, TXT, JSON (Art und Größe prüft zusätzlich die Datenbank). Die Datei geht im Binärfeld "datei" an
// "TALENTS Zahlen auslesen"; das Talent bestimmt die Datenbank mit den Rechten des Absenders (nur zuständige Talents).
const b = $('Datei vom Listener-Bot').item.json.body || {};
const an = $json.an === true;
const beschriftung = String(b.caption || '').trim();
// Trenner nötig (Leerzeichen, "für", "von", ":" oder "-"), damit z. B. "Zahlenbeleg" ein Beleg bleibt
const m = beschriftung.match(/^\s*(zahlen|statistik|insights)(?:\s+(?:für|von)\s+|\s*[:\-]\s*|\s+)(.+)$/i);
const talent = m ? m[2].trim().slice(0, 120) : '';
const name = String(b.filename || 'datei').slice(0, 120);
const ende = (name.split('.').pop() || '').toLowerCase();
let mime = String(b.mimetype || '').toLowerCase().split(';')[0].trim();
if (mime === 'image/jpg') mime = 'image/jpeg';
const NACH_ENDUNG = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp', pdf: 'application/pdf', csv: 'text/csv', txt: 'text/plain', json: 'application/json' };
if (!mime || mime === 'application/octet-stream') mime = NACH_ENDUNG[ende] || mime;
const ERLAUBT = ['image/png', 'image/jpeg', 'image/webp', 'application/pdf', 'text/csv', 'text/plain', 'application/json'];
let weg = 'beleg';
if (an && talent) weg = ERLAUBT.includes(mime) && !!b.data_base64 ? 'talent' : 'talent_typ';
const out = { json: { weg, quelle: 'chat', nutzer: String(b.sender || ''), talent: weg === 'beleg' ? '' : talent, datei_name: name, mimetype: mime, room_id: b.room_id, sender: b.sender, event_id: b.event_id } };
if (weg === 'talent') out.binary = { datei: await this.helpers.prepareBinaryData(Buffer.from(b.data_base64, 'base64'), name, mime) };
return out;

// Antwort an den Absender (Stefan 18.10.2026, Vertrag Migration 47 §6): Text aus "TALENTS Zahlen auslesen" bzw. Hinweis zum Dateityp.
// Das ist die Antwort im Gespräch, keine selbst verschickte Nachricht. Gespeichert wird erst nach Bestätigung auf der Seite des Talents.
const P = $('Talents-Datei prüfen').first().json;
const ohneEmoji = v => String(v ?? '').replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, '').trim();
let text;
if (P.weg === 'talent_typ') {
  text = 'Diese Datei (' + P.datei_name + ') kann ich für Talent-Zahlen nicht lesen. Bitte als Bild (PNG, JPG, WEBP), PDF, CSV, TXT oder JSON schicken.';
} else {
  const r = $input.first().json || {};
  const kand = Array.isArray(r.kandidaten) ? r.kandidaten.map(k => String((k && (k.anzeigename || k.name)) || '').trim()).filter(Boolean).slice(0, 10) : [];
  if (r.error || (!r.text && r.ok !== true)) text = 'Die Zahlen konnten gerade nicht ausgelesen werden. Bitte später noch einmal schicken oder die Datei auf der Seite des Talents unter „Zahlen ohne Verbindung“ hochladen.';
  else if (kand.length) text = ohneEmoji(r.text || 'Welches Talent meinst du?') + '\n\nInfrage kommen: ' + kand.join(', ') + '. Bitte die Datei noch einmal mit der Beschriftung „Zahlen <Name>“ schicken.';
  else text = ohneEmoji(r.text);
}
return [{ json: { room_id: P.room_id, text: String(text).slice(0, 2000) } }];

// Dateien im Chat nimmt die Installation nur als Talent-Zahlen an (Beschriftung „Zahlen <Name>“)
const b = $('Datei vom Listener-Bot').first().json.body || {};
return [{ json: { room_id: b.room_id, text: 'Diese Datei kann ich hier nicht verarbeiten. Talent-Zahlen bitte mit der Beschriftung „Zahlen <Name>“ schicken.' } }];
